import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ─────────────────────────────────────────────────────────────────
  // 1. GEOMETRY & MATERIAL
  // ─────────────────────────────────────────────────────────────────

  const geometry = new THREE.PlaneGeometry(0.8, 0.32); // Capsule proportions

  // Load ceramic grain texture for tactile badge surface
  let baseTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (baseTexture === null && material) {
        baseTexture = tex;
        tex.wrapS = THREE.RepeatWrapping;
        tex.wrapT = THREE.RepeatWrapping;
        material.colorNode = tex;
        material.needsUpdate = true;
      }
    });
  }

  // TSL-based material with accent edge glow
  const colorNode = baseTexture
    ? baseTexture
    : uniform(new THREE.Color('#e8ecf2'));

  const edgeGlow = smoothstep(0.15, 0.0, mix(
    Math.abs(uv().x - 0.5) * 2,
    Math.abs(uv().y - 0.5) * 2,
    0.5
  ).sub(0.48));

  const accentColor = uniform(new THREE.Color('#ff2a38'));
  const finalColor = mix(colorNode, accentColor, edgeGlow.mul(0.35));

  const material = new MeshBasicNodeMaterial({
    colorNode: finalColor,
    side: THREE.DoubleSide,
    toneMapped: true,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(config.scenePosition?.[0] ?? 0, config.scenePosition?.[1] ?? 0, config.scenePosition?.[2] ?? 0);
  mesh.rotation.set(config.scenePosition?.[3] ?? 0, config.scenePosition?.[4] ?? 0, config.scenePosition?.[5] ?? 0);
  mesh.scale.set(config.scenePosition?.[6] ?? 1, config.scenePosition?.[7] ?? 1, config.scenePosition?.[8] ?? 1);

  // ─────────────────────────────────────────────────────────────────
  // 2. LIGHTING: Accent rim to emphasize badge edge
  // ─────────────────────────────────────────────────────────────────

  const group = new THREE.Group();
  group.add(mesh);

  // Accent rim light (mounted on group, not scene — local to this badge)
  const rimLight = new THREE.PointLight('#ff2a38', 0.7, 3.0);
  rimLight.position.set(0.3, 0.15, 0.5);
  group.add(rimLight);

  // ─────────────────────────────────────────────────────────────────
  // 3. INTERACTION: Hover lift + Click select
  // ─────────────────────────────────────────────────────────────────

  const timelines = [];
  const basePosition = new THREE.Vector3(
    mesh.position.x,
    mesh.position.y,
    mesh.position.z
  );

  mesh.userData.handlers = {
    hover: {
      enter: () => {
        const tl = gsap.timeline();
        tl.to(mesh.position, {
          y: basePosition.y + 0.15,
          duration: 0.6,
          ease: 'power3.out',
        }, 0);
        tl.to(rimLight, {
          intensity: 1.2,
          duration: 0.6,
          ease: 'power3.out',
        }, 0);
        timelines.push(tl);
      },
      exit: () => {
        const tl = gsap.timeline();
        tl.to(mesh.position, {
          y: basePosition.y,
          duration: 0.5,
          ease: 'power2.inOut',
        }, 0);
        tl.to(rimLight, {
          intensity: 0.7,
          duration: 0.5,
          ease: 'power2.inOut',
        }, 0);
        timelines.push(tl);
      },
    },
    click: () => {
      // Press-down feedback
      const pressTl = gsap.timeline();
      pressTl.to(mesh.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
      }, 0);
      pressTl.to(mesh.scale, {
        x: 1.0,
        y: 1.0,
        duration: 0.4,
        ease: 'power4.out',
      }, 0.12);
      timelines.push(pressTl);

      // Emit navigation event
      ctx.emit('navigate', { to: 'hub-pricing' });
    },
  };

  // ─────────────────────────────────────────────────────────────────
  // 4. CLEANUP
  // ─────────────────────────────────────────────────────────────────

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    geometry.dispose();
    material.dispose();
    if (baseTexture) baseTexture.dispose();
  };

  return group;
}
